struct StudyRootView: View {
    @ObservedObject var shell: CrosswakeShell

    var body: some View {
        switch shell.presentation {
        case let .liveView(session), let .offlineIsland(session):
            StudyWebView(session: session, shell: shell)
                .ignoresSafeArea(.container, edges: .bottom)
                .overlay(alignment: .topLeading) { TwinReadyMarker() }
        case let .denied(denial):
            VStack(spacing: 8) {
                Text(denial.title).font(.headline)
                Text(denial.message).font(.subheadline).foregroundColor(.secondary)
            }
            .padding()
        default:
            ProgressView()
        }
    }
}

/// One-bit readiness marker for the run's UI test. It is present only while the twin host
/// driver reports the study document as activated, and it carries no study content.
struct TwinReadyMarker: View {
